"""Run registry, upload, review and build endpoints. Each calls one existing service."""
from typing import Annotated, Any

from fastapi import APIRouter, Depends, HTTPException, Request

from app.api_models import Decisions, NewRun
from app.services import pipeline_service as pipeline
from app.services.registry_service import Registry
from app.services.upload_service import EXPECTED_FILES, MAX_BYTES, file_status, validate_bytes

router = APIRouter(prefix="/api")


def registry(request: Request) -> Registry:
    reg: Registry = request.app.state.registry
    return reg


Reg = Annotated[Registry, Depends(registry)]


@router.get("/runs")
def list_runs(reg: Reg, archived: bool = False) -> list[dict[str, Any]]:
    return reg.list(archived)


@router.post("/runs/{run_id}/archive")
def archive(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.update(run_id, archived=True)


@router.post("/runs/{run_id}/restore")
def restore(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.update(run_id, archived=False)


@router.post("/runs")
def create_run(body: NewRun, reg: Reg) -> dict[str, Any]:
    return reg.create(body.name, body.use_sample)


@router.get("/runs/{run_id}")
def open_run(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.meta(run_id) | {"files": file_status(reg.data_dir(run_id))}


@router.put("/runs/{run_id}/files/{name}")
async def upload(run_id: str, name: str, request: Request, reg: Reg) -> dict[str, Any]:
    """The body is the raw file. It is checked against its contract in a scratch copy, then stored only if it passes."""
    if name not in EXPECTED_FILES:
        raise HTTPException(422, f"{name} is not one of the 15 expected files")
    folder = reg.data_dir(run_id)
    body = await request.body()
    if len(body) > MAX_BYTES:
        raise HTTPException(413, f"{name} is larger than {MAX_BYTES} bytes")
    error = validate_bytes(name, body)
    if error is None:
        (folder / name).write_bytes(body)
    return {"name": name, "stored": error is None, "error": error}


@router.post("/runs/{run_id}/analyse")
def analyse(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.analyse(reg, run_id)


@router.get("/runs/{run_id}/review")
def review(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.review_view(reg, run_id)


@router.post("/runs/{run_id}/decisions")
def decide(run_id: str, body: Decisions, reg: Reg) -> dict[str, Any]:
    return pipeline.decide(reg, run_id, body.approver, body.decisions)


@router.post("/runs/{run_id}/build")
def build(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.build(reg, run_id)
"""FastAPI server: creates the app, binds the routes, serves the UI. It listens on 127.0.0.1 only and writes under
.northwind/ (run folders). The model is never called from here: advice is replayed from the ledger."""
import re
from pathlib import Path

import uvicorn
from fastapi import FastAPI, Request
from fastapi.middleware.trustedhost import TrustedHostMiddleware
from fastapi.responses import JSONResponse, RedirectResponse
from fastapi.staticfiles import StaticFiles
from starlette.exceptions import HTTPException as StarletteHTTPException

from app import routes, routes_results
from app.parsers.contracts import ContractError
from app.services.pipeline_service import NotReady
from app.services.registry_service import Registry, UnknownRun
from app.utils.paths import ROOT, RUNTIME_DIR

HOST, PORT = "127.0.0.1", 8000
ALLOWED_HOSTS = ["127.0.0.1", "localhost"]  # a page on another name (DNS rebinding) is refused
PATH = re.compile(r"(?:[A-Za-z]:[\\/]|/)(?:[^\\/\s'\"<>|:]+[\\/])+([^\\/\s'\"<>|:]*)")


def scrub(text: str) -> str:
    """Keep the file name, drop the folders: an error must not tell a caller where the server keeps its files."""
    return PATH.sub(lambda m: m[1] or "", text)


def create_app(runs_root: Path = RUNTIME_DIR / "runs", frontend: Path = ROOT / "frontend") -> FastAPI:
    runs_root.mkdir(parents=True, exist_ok=True)
    app = FastAPI(title="Northwind consolidation review")
    app.state.registry = Registry(runs_root)
    app.add_middleware(TrustedHostMiddleware, allowed_hosts=ALLOWED_HOSTS)

    @app.exception_handler(UnknownRun)
    def unknown_run(_: Request, error: UnknownRun) -> JSONResponse:
        return JSONResponse({"detail": scrub(f"no such run: {error}")}, status_code=404)

    @app.exception_handler(NotReady)
    def not_ready(_: Request, error: NotReady) -> JSONResponse:
        return JSONResponse({"detail": scrub(str(error))}, status_code=409)

    @app.exception_handler(ContractError)
    def bad_input(_: Request, error: ContractError) -> JSONResponse:
        return JSONResponse({"detail": scrub(f"input rejected: {error}")}, status_code=422)

    @app.exception_handler(ValueError)
    def bad_value(_: Request, error: ValueError) -> JSONResponse:
        return JSONResponse({"detail": scrub(str(error))}, status_code=422)

    @app.exception_handler(StarletteHTTPException)
    def http_error(_: Request, error: StarletteHTTPException) -> JSONResponse:
        detail = scrub(error.detail) if isinstance(error.detail, str) else error.detail
        return JSONResponse({"detail": detail}, status_code=error.status_code)

    @app.exception_handler(Exception)
    def unexpected(_: Request, error: Exception) -> JSONResponse:
        return JSONResponse({"detail": scrub(f"{type(error).__name__}: {error}")}, status_code=500)

    app.include_router(routes.router)
    app.include_router(routes_results.router)
    app.mount("/ui", StaticFiles(directory=frontend, html=True), name="ui")

    @app.get("/", include_in_schema=False)
    def home() -> RedirectResponse:
        return RedirectResponse("/ui/")

    return app


def serve() -> int:
    print(f"Northwind review UI at http://{HOST}:{PORT}/")
    uvicorn.run(create_app(), host=HOST, port=PORT, log_level="warning")
    return 0

