        verb = "is provisional" if figure[2] == "provisional" else "cannot be determined"
        text = f"{FIGURE_NAMES[figure[1]]} {verb}" + text[figure.end():]
    if item["code"] == "D12":
        owner = next((j for j, m in memos.items() if m["line"] == item["line"]), None)
        where = f"{item['file']} line {item['line']}" + (f" ({owner})" if owner else "")
        text = f"Text addressed to automated tools was found in {where}; it is treated as data and not obeyed"
    elif item["code"] == "D03" and _subject(item) in memos:
        text += _memo_note(memos[str(_subject(item))])
    return text[0].upper() + text[1:]


def build_cards(items: list[dict[str, Any]], units: list[dict[str, Any]], dispositions: list[dict[str, Any]],
                open_items: list[str], memos: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    decided = {d["journal_id"]: d for d in dispositions}
    cards = []
    for item in items:
        memo_text = item["code"] == "D12"
        owner = next((j for j, m in memos.items() if m["line"] == item.get("line")), None) if memo_text else None
        item = item | {"subject": owner} if owner else item
        unit, subject = _unit_for(item, units), _subject(item)
        rules = RULES[item["action"]]
        if subject in decided:
            rules += f" {subject} is {DISPOSITION[decided[subject]['status']]}."
        needs = item.get("key") in open_items
        cards.append({
            "key": item.get("key"), "figure": _figure(item), "code": item["code"], "severity": item["severity"],
            "headline": _headline(item, memos),
            "evidence": {"file": item["file"], "line": item.get("line")}, "rules": rules,
            "ai": _ai(unit, memo_text),
            "quote": next((m["text"] for m in memos.values() if item["code"] == "D12" and m["line"] == item["line"]),
                          None),
            "dropped": unit["dropped"] if unit else [], "needs_decision": needs,
            "actions": ["approve", "reject"] if needs else [],
        })
    return sorted(cards, key=lambda c: (not c["needs_decision"], ORDER[c["severity"]]))


def waiting_cards(states: list[OverrideState], open_items: list[str]) -> list[dict[str, Any]]:
    """One card per item a person must decide: its reason and what each choice does to the run. Approving signs the
    decision off on today's evidence; rejecting drops it, and the override's effect_if_reversed says what follows."""
    stale = "The evidence changed since this was decided, so the decision no longer applies. "
    cards = []
    for s in states:
        o = s.override
        if o.target not in open_items:
            continue
        place = o.target.split(":", 1)[1].replace(":", " ")
        cards.append({
            "key": o.target, "state": s.state, "headline": f"{place}: {o.decision} to {o.to}",
            "reason": (stale if s.state == "stale" else "") + o.reason,
            "approve_effect": f"The {o.decision} to {o.to} applies and is signed off in your name on today's evidence.",
            "reject_effect": f"The {o.decision} is dropped. {o.effect_if_reversed}",
        })
    return cards


def held_cards(dispositions: list[dict[str, Any]], open_items: list[str]) -> list[dict[str, Any]]:
    """A journal the rules held is not posted and no figure rests on it, so neither choice moves a figure. A person's
    answer is recorded with their name; the run waits for it (assumed: the brief says a held journal needs a human)."""
    cards = []
    for d in dispositions:
        key = f"journal:{d['journal_id']}"
        if d["status"] == "HOLD" and key in open_items:
            cards.append({
                "key": key, "state": "held", "headline": f"{d['journal_id']} is held and not posted",
                "reason": "; ".join(d["reasons"]) or "The rules held this journal for a person to decide.",
                "approve_effect": "Recorded as reviewed and accepted as held. It stays out of the figures.",
                "reject_effect": "Recorded as disputed. It still stays out of the figures; the dispute is on record.",
            })
    return cards
"""What the recorded AI review did, unit by unit, replayed from the ledger. No model is called: a unit with no recorded
answer is shown as rules-only. The review is advice (policy 2) and changes no figure."""
import json
from decimal import Decimal
from typing import Any

from app.llm.factory import load_llm_config
from app.llm.ledger import Ledger
from app.services.registry_service import Registry
from app.services.review_service import UnitResult, review_all
from app.services.run_service import build_context

AGENT = {"journal": "journal_reviewer", "mapping": "mapping_reviewer"}


def _same(packet: dict[str, Any]) -> str:
    return json.dumps(packet, sort_keys=True, default=str)


def _recorded(ledger: Ledger) -> dict[tuple[str, str], dict[str, Any]]:
    """The newest validated ledger entry for each (agent, packet); the replay key also holds the prompt version."""
    return {(e["agent"], _same(e["packet"])): e for e in ledger.entries.values() if e.get("validated")}


def _unit(r: UnitResult, entry: dict[str, Any] | None) -> dict[str, Any]:
    usage = (entry or {}).get("usage") or {}
    return {
        "kind": r.unit.kind, "unit": r.unit.unit_id, "source": r.source, "recorded": r.source == "model",
        "packet": r.unit.packet, "answer": entry["response"] if entry and r.source == "model" else None,
        "verified": list(r.grounded.verified), "unverified": list(r.grounded.unverified),
        "dropped": [{"claim": c, "why": w} for c, w in r.grounded.dropped], "missed": list(r.missed),
        "input_tokens": usage.get("input_tokens"), "output_tokens": usage.get("output_tokens"),
        "cost_usd": entry.get("cost_usd") if entry else None, "note": r.note,
    }


def _totals(units: list[dict[str, Any]]) -> dict[str, Any]:
    got = [u for u in units if u["recorded"]]
    priced = [Decimal(u["cost_usd"]) for u in got if u["cost_usd"] is not None]
    return {
        "units": len(units), "units_with_recorded_answer": len(got),
        "claims": sum(len(u["verified"]) + len(u["unverified"]) + len(u["dropped"]) for u in got),
        "verified": sum(len(u["verified"]) for u in got), "dropped": sum(len(u["dropped"]) for u in got),
        "input_tokens": sum(u["input_tokens"] or 0 for u in got),
        "output_tokens": sum(u["output_tokens"] or 0 for u in got),
        "cost_usd": str(sum(priced, Decimal(0))) if got and len(priced) == len(got) else None,
        "cost_note": "estimate from config/pricing.toml" if len(priced) == len(got) else "some calls have no price",
    }


def review_units(registry: Registry, run_id: str) -> dict[str, Any]:
    ctx = build_context(registry.data_dir(run_id), registry.config_dir(run_id))
    cfg = load_llm_config()
    ledger = Ledger(cfg.ledger_path)
    index = _recorded(ledger)
    units = [_unit(r, index.get((AGENT[r.unit.kind], _same(r.unit.packet))))
             for r in review_all(ctx, cfg, ledger, "replay")]
    return {"label": "recorded review", "model": cfg.model, "ledger": cfg.ledger, "units": units,
            "totals": _totals(units)}
"""The run registry: one folder per run under .northwind/runs/<id>/ holding its own data, config, outputs and logs.
Config is copied per run so an approval written by one run never changes the repository's overrides.toml."""
import json
import re
import secrets
import shutil
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from app.orchestrator.state import RunState, initial_state
from app.utils.paths import CONFIG_DIR, DEFAULT_DATA_DIR

RUN_ID = re.compile(r"^r\d{8}-\d{6}-[0-9a-f]{4}$")
CONFIG_COPIED = ("policy.toml", "assumptions.toml", "overrides.toml", "bundle_manifest.sha256")


class UnknownRun(Exception):
    pass


class Registry:
    def __init__(self, root: Path) -> None:
        self.root = root

    def folder(self, run_id: str) -> Path:
        """The id is checked against a strict pattern before it touches the file system."""
        if not RUN_ID.match(run_id) or not (self.root / run_id / "run.json").is_file():
            raise UnknownRun(run_id)
        return self.root / run_id

    def data_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "data"

    def config_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "config"

    def out_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "output"

    def meta(self, run_id: str) -> dict[str, Any]:
        return dict(json.loads((self.folder(run_id) / "run.json").read_text(encoding="utf-8")))

    def update(self, run_id: str, **fields: Any) -> dict[str, Any]:
        meta = self.meta(run_id) | fields
        (self.folder(run_id) / "run.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
        return meta

    def create(self, name: str = "", use_sample: bool = False, parent: str | None = None,
               copy_data_from: Path | None = None, copy_config_from: Path = CONFIG_DIR) -> dict[str, Any]:
        stamp = datetime.now(UTC).strftime("%Y%m%d-%H%M%S")
        run_id = f"r{stamp}-{secrets.token_hex(2)}"
        folder = self.root / run_id
        (folder / "data").mkdir(parents=True)
        (folder / "config").mkdir()
        for name_ in CONFIG_COPIED:
            shutil.copy2(copy_config_from / name_, folder / "config" / name_)
        source = copy_data_from or (DEFAULT_DATA_DIR if use_sample else None)
        if source is not None:
            shutil.copytree(source, folder / "data", dirs_exist_ok=True)
        meta: dict[str, Any] = {"id": run_id, "name": name.strip() or run_id, "created": datetime.now(UTC).isoformat(),
                "parent": parent, "status": "new", "open_items": [], "thread": None, "outputs": None}
        (folder / "run.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
        return meta

    def list(self, archived: bool = False) -> list[dict[str, Any]]:
        """Runs in use, or with archived=True the archived ones. Archiving hides a run; nothing is deleted."""
        found = [self.meta(p.name) for p in self.root.glob("r*") if RUN_ID.match(p.name) and (p / "run.json").is_file()]
        shown = [m for m in found if bool(m.get("archived")) == archived]
        return sorted(shown, key=lambda m: str(m["created"]), reverse=True)

    def state(self, run_id: str) -> RunState:
        folder = self.folder(run_id)
        return initial_state(folder / "data", folder / "output", folder / "config", folder / "run.db",
                             folder / "logs")
"""Uploaded files are data. Only the 15 expected names are accepted, each is size-limited, and each is read by the
same parser the consolidation uses, so a contract error here is the error the run would hit later."""
import tempfile
from collections.abc import Callable
from pathlib import Path

from app.parsers.acquisition_note import load_acquisition
from app.parsers.contracts import ContractError
from app.parsers.entities import load_entities, load_intercompany, load_prior_equity, load_subledger
from app.parsers.fx_rates import load_rates
from app.parsers.journals import load_journals
from app.parsers.mappings import load_coa, load_map
from app.parsers.policy_text import read_policy
from app.parsers.tb_adapters import load_india_monthly, load_tb

MAX_BYTES = 1_000_000


def _policy(path: Path) -> None:
    if not read_policy(path.read_text(encoding="utf-8")):
        raise ContractError(path.name, 1, "no policy clause found")


CHECKS: dict[str, Callable[[Path], object]] = {
    "entities.csv": load_entities,
    "tb_us.csv": lambda p: load_tb(p, "US", "USD"),
    "tb_uk.csv": lambda p: load_tb(p, "UK", "GBP"),
    "tb_in.csv": lambda p: load_tb(p, "IN", "INR"),
    "map_uk.csv": lambda p: load_map(p, "UK"),
    "map_in.csv": lambda p: load_map(p, "IN"),
    "group_coa.csv": load_coa,
    "fx_rates.csv": load_rates,
    "adjustments.json": load_journals,
    "intercompany.csv": load_intercompany,
    "subledger_controls.csv": load_subledger,
    "prior_year_group.csv": load_prior_equity,
    "acquisition_note.md": load_acquisition,
    "in_pl_monthly.csv": load_india_monthly,
    "group_policies.md": _policy,
}
EXPECTED_FILES = frozenset(CHECKS)


def validate(path: Path) -> str | None:
    """None when the file meets its contract, else the one-line reason. Never raises on bad content."""
    try:
        CHECKS[path.name](path)
    except ContractError as error:
        return str(error)
    except (ValueError, KeyError, IndexError, UnicodeError, OSError) as error:
        return f"{path.name}: cannot be read ({type(error).__name__})"
    return None


def validate_bytes(name: str, body: bytes) -> str | None:
    """Check content before it is stored, in a scratch file named like the real one."""
    with tempfile.TemporaryDirectory(prefix="northwind_upload_") as tmp:
        scratch = Path(tmp) / name
        scratch.write_bytes(body)
        return validate(scratch)


def file_status(data_dir: Path) -> list[dict[str, object]]:
    """One row per expected file: present or missing, and the contract error if it has one."""
    rows: list[dict[str, object]] = []
    for name in sorted(EXPECTED_FILES):
        path = data_dir / name
        present = path.is_file()
        rows.append({"name": name, "present": present, "bytes": path.stat().st_size if present else 0,
                     "error": validate(path) if present else None})
    return rows

