"""The same nodes run in order without LangGraph: the fallback, and the other side of the equivalence test."""
from app.orchestrator.edges import after_analyse
from app.orchestrator.nodes import Answer, analyse, apply_answer, consolidate, export, intake
from app.orchestrator.state import RunState


def run_plain(state: RunState, answer: Answer | None = None) -> RunState:
    """With items waiting and no answer the run stops at the human gate, as the graph does when it pauses."""
    state = RunState(**{**state, **intake(state)})
    state = RunState(**{**state, **analyse(state)})
    if after_analyse(state) == "resolve":
        if answer is None:
            return RunState(**{**state, "status": "awaiting_review"})
        state = RunState(**{**state, **apply_answer(state, answer)})
    for node in (consolidate, export):
        state = RunState(**{**state, **node(state)})
    return state
"""One function per stage, shared by the LangGraph graph and the plain runner. Each returns a partial state update.

A node rebuilds what it needs from the files named in the state (the whole run takes about 20 ms), so nothing large
has to be checkpointed and a resumed process starts from the same bytes."""
from pathlib import Path
from typing import Any

from app.config import load_overrides
from app.detectors.registry import run_all
from app.orchestrator.state import RunState
from app.services.overrides_service import approve, override_states, reject
from app.services.run_service import build_context, input_hash, record, stage, write_outputs
from app.utils.hashing import sha256_file
from app.utils.logging import RunLogger

Answer = dict[str, Any]


def _log(state: RunState, stage_name: str, event: str, **fields: object) -> None:
    """Every stage of one execution appends to the file that intake started."""
    existing = Path(state["log_file"]) if "log_file" in state else None
    log = RunLogger(Path(state["log_dir"]), state["run_id"], existing)
    log.event(stage_name, event, **fields)
    log.close()


def intake(state: RunState) -> RunState:
    run_id = input_hash(Path(state["data_dir"]), Path(state["config_dir"]))[:16]
    log = RunLogger(Path(state["log_dir"]), run_id)
    log.event("intake", "inputs read", data_dir=state["data_dir"])
    log.close()
    return RunState(run_id=run_id, status="intake", log_file=str(log.path))


def analyse(state: RunState) -> RunState:
    """Run the detectors and list the overrides a person still has to sign off or re-decide."""
    ctx = build_context(Path(state["data_dir"]), Path(state["config_dir"]))
    findings = run_all(ctx)
    states = override_states(load_overrides(Path(state["config_dir"]) / "overrides.toml"), ctx.inputs)
    waiting = [s.override.target for s in states if s.state in {"open", "stale"}]
    for f in findings:
        _log(state, "analyse", "finding", finding_key=f.key, code=f.code, severity=f.severity, action=f.action)
    _log(state, "analyse", "findings", count=len(findings), waiting=waiting)
    return RunState(status="analysed", open_items=waiting)


def apply_answer(state: RunState, answer: Answer) -> RunState:
    """A person's answer: {'approver': name, 'decisions': {target: 'approve' | 'reject'}}. The rest stay open."""
    config_dir = Path(state["config_dir"])
    inputs = build_context(Path(state["data_dir"]), config_dir).inputs
    decided: list[str] = []
    for target in state.get("open_items", []):
        choice = answer.get("decisions", {}).get(target)
        if choice == "approve":
            approve(config_dir / "overrides.toml", inputs, target, answer["approver"])
        elif choice == "reject":
            reject(config_dir / "overrides.toml", target, answer["approver"])
        else:
            continue
        decided.append(target)
    remaining = [t for t in state.get("open_items", []) if t not in decided]
    _log(state, "resolve", "answered", decided=decided, approver=answer.get("approver"))
    return RunState(status="resolved", open_items=remaining, decided=decided)


def consolidate(state: RunState) -> RunState:
    run = stage(build_context(Path(state["data_dir"]), Path(state["config_dir"])))
    for d in run.dispositions:
        _log(state, "consolidate", "journal disposition", journal=d.journal_id, status=d.status)
    for c in run.checks:
        _log(state, "verify", "gate", check=c.name, passed=c.ok)
    _log(state, "consolidate", "done", blocked=run.blocked, checks_passed=run.checks_passed)
    return RunState(status="consolidated", blocked=run.blocked, checks_passed=run.checks_passed)


def export(state: RunState) -> RunState:
    config_dir, out_dir = Path(state["config_dir"]), Path(state["out_dir"])
    run = stage(build_context(Path(state["data_dir"]), config_dir))
    write_outputs(run, out_dir, config_dir)
    record(run, Path(state["db_path"]), Path(state["config_dir"]))
    hashes = {p.name: sha256_file(p) for p in sorted(out_dir.iterdir()) if p.is_file()}
    _log(state, "export", "outputs written", folder=str(out_dir))
    _log(state, "run", "finished", blocked=run.blocked, checks_passed=run.checks_passed)
    return RunState(status="done", output_hashes=hashes)
"""Routing shared by both runners: the human gate is only entered when something is waiting for a person."""
from app.orchestrator.state import RunState


def after_analyse(state: RunState) -> str:
    return "resolve" if state.get("open_items") else "consolidate"
"""Human decisions on findings: which overrides apply, which are stale, and the review queue."""
import re
from dataclasses import dataclass
from pathlib import Path

from app.domain.findings import Finding
from app.domain.policy import Override
from app.domain.runs import Inputs
from app.parsers.mappings import classify_all
from app.utils.hashing import json_hash


@dataclass(frozen=True)
class OverrideState:
    """`applied` and `open` change the run; `stale` and `rejected` do not."""

    override: Override
    state: str


def evidence_hash(inputs: Inputs, target: str) -> str | None:
    """What the reviewer looked at: the mapping row and the trial balance row of 'mapping:UK:2310'."""
    kind, entity, code = target.split(":")
    if kind != "mapping":
        return None
    for line in classify_all(inputs.trial_balances, inputs.maps, inputs.coa):
        if (line.line.entity, line.line.local_code) == (entity, code) and line.map_ref is not None:
            return json_hash([line.map_ref.row_hash, line.line.ref.row_hash])
    return None


def override_states(rows: list[Override], inputs: Inputs) -> list[OverrideState]:
    """A decision made on evidence that has since changed is stale: it stops applying and returns to the queue."""
    states = []
    for row in rows:
        if row.status == "rejected":
            states.append(OverrideState(row, "rejected"))
        elif row.evidence_hash != evidence_hash(inputs, row.target):
            states.append(OverrideState(row, "stale"))
        else:
            states.append(OverrideState(row, "applied" if row.status == "approved" else "open"))
    return states


def active_overrides(rows: list[Override], inputs: Inputs) -> list[Override]:
    return [s.override for s in override_states(rows, inputs) if s.state in {"applied", "open"}]


def review_queue(findings: list[Finding], states: list[OverrideState]) -> list[dict[str, str]]:
    """Open and stale overrides first, then every finding a person still has to look at. Notes are not queued."""
    queue = [{"kind": "override", "key": s.override.target, "state": s.state, "reason": s.override.reason}
             for s in states if s.state in {"open", "stale"}]
    for f in findings:
        mapping_decided = f.code == "D02" and f.action == "assumed" and bool(states)
        if f.severity != "NOTE" and not mapping_decided:
            queue.append({"kind": "finding", "key": f.key, "state": f.action, "reason": f.claim})
    return queue


def approve(path: Path, inputs: Inputs, target: str, approver: str) -> None:
    """Sign a decision off on the evidence as it stands now: sets approver, status and evidence_hash in the file."""
    _rewrite(path, target, {"approver": approver, "status": "approved", "evidence_hash": evidence_hash(inputs, target)})


def reject(path: Path, target: str, approver: str) -> None:
    _rewrite(path, target, {"approver": approver, "status": "rejected"})


def _rewrite(path: Path, target: str, fields: dict[str, str | None]) -> None:
    text = path.read_text(encoding="utf-8")
    blocks = re.split(r"(?m)^(?=\[\[override\]\])", text)
    for i, block in enumerate(blocks):
        if f'target = "{target}"' not in block:
            continue
        for name, value in fields.items():
            line = f'{name} = "{value}"'
            pattern = rf'(?m)^{name} = ".*"$'
            block = re.sub(pattern, line, block) if re.search(pattern, block) else block.rstrip("\n") + f"\n{line}\n"
        blocks[i] = block
        path.write_text("".join(blocks), encoding="utf-8", newline="")
        return
    raise KeyError(f"no override for {target}")
"""The one way tests run the whole pipeline: the same nodes the command line and the graph use."""
from pathlib import Path

from app.orchestrator.runner_plain import run_plain
from app.orchestrator.state import RunState, initial_state
from app.utils.paths import CONFIG_DIR


def run_pipeline(data_dir: Path, out_dir: Path, db_path: Path, log_dir: Path | None = None) -> RunState:
    state = initial_state(data_dir, out_dir, CONFIG_DIR, db_path, log_dir or db_path.parent / "logs")
    return run_plain(state)
