    for agent in FULL_AGENTS:
        names = {p.name for p in (ROOT / "app/agents" / agent).iterdir() if p.is_file()}
        assert names == {"__init__.py", *AGENT_FILES}, agent


def test_stretch_agents_hold_only_an_init_file() -> None:
