import re
def sub(p,a,b):
    s=open(p,encoding='utf-8').read(); assert a in s,a; open(p,'w',encoding='utf-8').write(s.replace(a,b,1))
p='frontend/app.js'
s=open(p,encoding='utf-8').read()
start=s.index('async function runsList()')
end=s.index('// A step that needs a finished run')
new='''// Stage 0, Home: continue a run by its id, or create a new one. The list of runs stays below for a run you did not note down.
async function runsList() {
  drawStepper(null);
  const showArchived = location.hash === "#/archived";
  const runs = await api("GET", showArchived ? "/runs?archived=true" : "/runs");
  const keep = (r, what) => async () => { try { await api("POST", `/runs/${r.id}/${what}`); await route(); } catch (e) { fail(e); } };
  const problem = h("div", { class: "error", role: "alert", hidden: true });
  const say = (text) => { problem.textContent = text; problem.hidden = !text; };
  const runId = h("input", { placeholder: "r20261118-101500-ab12", size: 26, "aria-label": "Run id", autocomplete: "off" });
  const open = async () => {
    const id = runId.value.trim();
    if (!id) return say("Enter a run id first.");
    try { const run = await api("GET", `/runs/${encodeURIComponent(id)}`); say(""); location.hash = `#/run/${run.id}/${nextStep(run)}`; }
    catch (e) { say(`No run with the id ${id} was found.`); }
  };
  const name = h("input", { placeholder: "run name", maxlength: 60, "aria-label": "Run name" });
  const sample = h("input", { type: "checkbox" });
  const create = async () => {
    try { const run = await api("POST", "/runs", { name: name.value, use_sample: sample.checked }); location.hash = `#/run/${run.id}/upload`; }
    catch (e) { fail(e); }
  };
  show(h("h1", {}, "Northwind consolidation review"),
    h("div", { class: "home" },
      h("section", { class: "card" }, h("h2", {}, "Continue a run"), h("p", { class: "muted" }, "Paste the id of a run you started before."),
        h("div", { class: "row" }, runId, h("button", { onclick: open }, "Open run"))),
      h("section", { class: "card" }, h("h2", {}, "Create a new run"),
        h("div", { class: "row" }, name), h("label", {}, sample, " start with the supplied sample files"),
        h("div", { class: "row" }, h("button", { onclick: create }, "Create new run")))),
    problem,
    h("h2", {}, showArchived ? "Archived runs" : "Recent runs"),
    runs.length ? table(["Name", "Id", "Status", "Created", "Based on", ""], runs.map((r) => [
      r.name, h("code", {}, r.id), h("span", { class: "tag" }, r.status), when(r.created), r.parent || "",
      h("span", { class: "row" }, h("a", { class: "btn plain", href: `#/run/${r.id}/${nextStep(r)}` },
        r.status === "awaiting_review" ? "Resume" : "Open"),
      h("button", { class: "plain", onclick: keep(r, showArchived ? "restore" : "archive") }, showArchived ? "Restore" : "Archive"))]))
      : h("p", { class: "muted" }, showArchived ? "No archived runs." : "No runs yet."),
    h("p", {}, h("a", { href: showArchived ? "#/" : "#/archived" }, showArchived ? "Back to runs" : "Show archived runs")));
}

'''
s=s[:start]+new+s[end:]
open(p,'w',encoding='utf-8').write(s)
p='frontend/steps.js'
s=open(p,encoding='utf-8').read()
start=s.index('async function uploadStep(run) {')
end=s.index('// Scan: the analysis runs')
new='''// Upload: one file at a time. Each of the 15 expected files has its own chooser and its own mark: uploaded, rejected
// with the contract's reason, or not uploaded. A file is stored only if it passes its contract.
async function uploadStep(run, notes = {}) {
  const fresh = await api("GET", `/runs/${run.id}`);
  const ready = fresh.files.every((f) => f.present && !f.error);
  const pick = (f) => h("input", { type: "file", "aria-label": `Choose ${f.name}`, onchange: async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    try {
      const r = await api("PUT", `/runs/${run.id}/files/${encodeURIComponent(f.name)}`, undefined, await file.arrayBuffer());
      notes[f.name] = r.stored ? null : r.error;
    } catch (err) { notes[f.name] = err.message; }
    await uploadStep(run, notes);
  } });
  const mark = (f) => notes[f.name] ? h("span", { class: "bad" }, "Rejected") :
    f.present && !f.error ? h("span", { class: "ok" }, "Uploaded") : h("span", { class: "muted" }, "Not uploaded");
  const rows = fresh.files.map((f) => [h("code", {}, f.name), mark(f), f.present ? `${f.bytes} bytes` : "",
    notes[f.name] || f.error || "", pick(f)]);
  const uploaded = fresh.files.filter((f) => f.present && !f.error).length;
  const next = () => go(run, "scan");
  show(...head(run, "1 Upload"), h("div", { class: "callout" }, "Add the files one at a time: choose a file on its own row. Only the 15 " +
    "expected names are accepted, up to 1 MB each, and a file that breaks its contract is refused with the reason shown."),
    h("p", { role: "status" }, `${uploaded} of ${fresh.files.length} files uploaded.`),
    table(["File", "Mark", "Size", "Contract", "Choose a file"], rows),
    h("div", { class: "row" }, h("button", { onclick: next, disabled: !ready }, "Next: scan the files")));
}

'''
s=s[:start]+new+s[end:]
open(p,'w',encoding='utf-8').write(s)
